const pageH1={overview:'Executive overview',sales:'Sales performance',budget:'Budget control',portfolio:'Product portfolio',markets:'Geographic markets',forecast:'Forecast & scenarios'};
const defaultPeriod=D.meta.lastClosedMonth || '2026-09';
const state={page:'overview',period:defaultPeriod,therapy:'ALL',market:'ALL',channel:'ALL',brand:'ALL',region:'ALL',scenario:'baseline',chartMonth:null,periodBeforeChart:null,...(initialState||{})};
const nf=new Intl.NumberFormat('en-GB',{maximumFractionDigits:1});
