const fmtUnits=n=>{let a=Math.abs(n);return (n<0?'−':'')+(a>=1e6?nf.format(a/1e6)+'m':a>=1e3?nf.format(a/1e3)+'k':nf.format(a))};
const pct=n=> Number.isFinite(n)?(n*100).toFixed(1)+'%':'—';
