function crossPairAttrs(region,therapy){return `aria-pressed="${state.region===region&&state.therapy===therapy}" data-cross-region="${q(region)}" data-cross-therapy="${q(therapy)}" role="button" tabindex="0" aria-label="Filter by ${q(region)} and ${q(therapy)}"`;}
function monthAttrs(month){const canDrill=state.page!=='forecast'&&(`${displayYear()}-${String(month).padStart(2,'0')}`<=defaultPeriod);return canDrill?`aria-pressed="${state.chartMonth===month}" data-cross-month="${month}" role="button" tabindex="0" aria-label="Set reporting cutoff to ${monthNames[month-1]}"`:'';}
