function add(a,b){return {sales:a.sales+b.sales,cogs:a.cogs+b.cogs,units:a.units+b.units}}
function yearData(){let year=displayYear(),end=displayMonth();let actual=aggregate('actual',year,end),budget=aggregate('budget',year,end),prev=year>2025?aggregate('actual',year-1,end):null;return {year,end,actual,budget,prev,variance:actual.sales-budget.sales,attainment:div(actual.sales,budget.sales),growth:prev?div(actual.sales-prev.sales,prev.sales):NaN,margin:div(actual.sales-actual.cogs,actual.sales),qStart:1+3*Math.floor((end-1)/3)} }
