function groupSummary(group){const {year,end}=yearData();let a=aggregate('actual',year,end,1,group),b=aggregate('budget',year,end,1,group),p=year>2025?aggregate('actual',year-1,end,1,group):new Map();return [...new Set([...a.keys(),...b.keys()])].map(key=>({key,actual:a.get(key)||empty(),budget:b.get(key)||empty(),prev:p.get(key)||empty()}))}
