 const hb=(r.budget/top)*plot.h; s+=`<rect ${monthAttrs(r.month)} x="${x+2}" y="${y(r.budget)}" width="${bw}" height="${hb}" rx="2" fill="${r.month>displayMonth()&&displayYear()===2026?'#e9eff5':'#bbdce3'}"><title>${r.name}: budget ${fmtEUR(r.budget)}</title></rect>`;
 if(r.actual>0){let ha=(r.actual/top)*plot.h;s+=`<rect ${monthAttrs(r.month)} x="${x-bw-2}" y="${y(r.actual)}" width="${bw}" height="${ha}" rx="2" fill="#1e6a9e"><title>${r.name}: net sales ${fmtEUR(r.actual)}; plan ${fmtEUR(r.budget)}; attainment ${pct(div(r.actual,r.budget))}</title></rect>`}
